/* WooCommerce Orders Invoice PDF — media upload handler */
( function ( $ ) {
	'use strict';

	$( document ).on( 'click', '.wpo-wcpdf-media-upload-button', function ( e ) {
		e.preventDefault();
		var $btn    = $( this );
		var target  = $btn.data( 'target' );
		var $input  = $( '#' + target );
		var $wrap   = $btn.closest( 'td, .wpo-wcpdf-media-wrap' );

		var frame = wp.media( {
			title:    $btn.text().trim(),
			multiple: false,
			library:  { type: 'image' },
			button:   { text: $btn.text().trim() },
		} );

		frame.on( 'select', function () {
			var attachment = frame.state().get( 'selection' ).first().toJSON();
			$input.val( attachment.id );

			var imgUrl = attachment.url;
			if ( attachment.sizes && attachment.sizes.thumbnail ) {
				imgUrl = attachment.sizes.thumbnail.url;
			}

			$wrap.find( '.wpo-wcpdf-logo-preview-link' ).remove();
			var $preview = $( '<a>', { href: '#', 'class': 'wpo-wcpdf-logo-preview-link', target: '_blank' } )
				.append( $( '<img>', { src: imgUrl, style: 'max-height:60px;display:block;margin-bottom:5px;' } ) );
			$input.after( $preview );

			if ( ! $wrap.find( '.wpo-wcpdf-media-remove-button' ).length ) {
				var $remove = $( '<button>', {
					type:  'button',
					'class': 'button wpo-wcpdf-media-remove-button',
					'data-target': target,
					text: $btn.closest( 'td, .wpo-wcpdf-media-wrap' ).find( '.wpo-wcpdf-media-remove-button' ).text() || 'Remove image',
				} );
				$btn.after( $remove );
			}

			$( document.body ).trigger( 'wpo-wcpdf-media-upload-setting-updated', [ target, attachment.id ] );
		} );

		frame.open();
	} );

	$( document ).on( 'click', '.wpo-wcpdf-media-remove-button', function ( e ) {
		e.preventDefault();
		var target = $( this ).data( 'target' );
		$( '#' + target ).val( '' );
		$( this ).closest( 'td, .wpo-wcpdf-media-wrap' ).find( '.wpo-wcpdf-logo-preview-link' ).remove();
		$( this ).remove();
		$( document.body ).trigger( 'wpo-wcpdf-media-upload-setting-updated', [ target, '' ] );
	} );

} )( jQuery );
